/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Uint8Array = require( '@stdlib/array/uint8' );
var ulpdiff = require( '@stdlib/number/float64/base/ulp-difference' );
var max = require( '@stdlib/math/base/special/max' );
var data = require( './fixtures/scipy/data.json' );


// FUNCTIONS //

/**
* Decodes JSON representations of non-finite floating-point values.
*
* @private
* @param {(number|string)} value - encoded value
* @returns {number} decoded value
*/
function decode( value ) {
	if ( value === 'nan' ) {
		return NaN;
	}
	if ( value === 'pinf' ) {
		return Infinity;
	}
	if ( value === 'ninf' ) {
		return -Infinity;
	}
	return value;
}

/**
* Asserts that a result agrees with the independently generated LAPACK oracle.
*
* @private
* @param {Object} t - test harness
* @param {number} actual - actual result
* @param {number} expected - expected result
* @param {string} message - test label
* @returns {void}
*/
function compare( t, actual, expected, message ) {
	if ( expected !== expected ) {
		t.strictEqual( actual !== actual, true, message );
	} else if ( expected === Infinity || expected === 0.0 ) {
		t.strictEqual( actual, expected, message );
	} else {
		t.ok( ulpdiff( actual, expected ) <= 8, message );
	}
}

/**
* Creates padded matrix storage with a nonzero backing-buffer byte offset.
*
* @private
* @param {Object} record - fixture record
* @param {integer} sa1 - row stride
* @param {integer} sa2 - column stride
* @param {NonNegativeInteger} oa - matrix offset
* @returns {Float64Array} matrix storage
*/
function storage( record, sa1, sa2, oa ) {
	var backing;
	var span;
	var out;
	var i;
	var j;

	span = oa + max( 0, (record.M-1)*sa1 ) + max( 0, (record.N-1)*sa2 ) + 4;
	backing = new Float64Array( span+3 );
	out = new Float64Array( backing.buffer, 24, span );
	for ( i = 0; i < out.length; i++ ) {
		out[ i ] = NaN;
	}
	for ( i = 0; i < record.M; i++ ) {
		for ( j = 0; j < record.N; j++ ) {
			out[ oa+(i*sa1)+(j*sa2) ] = decode( record.A[i][j] );
		}
	}
	return out;
}


// MAIN //

/**
* Registers the public, JavaScript, or native interface behavior suite.
*
* @private
* @param {Function} dlantr - interface to test
* @param {string} name - backend name
* @param {Object} [opts] - test options
* @returns {void}
*/
function suite( dlantr, name, opts ) {
	opts = opts || {};

	tape( name+': LAPACK oracle in padded row-major and column-major storage', opts, function test( t ) {
		var record;
		var before;
		var norms;
		var order;
		var work;
		var norm;
		var lda;
		var sa1;
		var sa2;
		var out;
		var A;
		var i;
		var j;
		var k;

		norms = [ 'max', 'one', 'infinity', 'frobenius' ];
		for ( i = 0; i < data.records.length; i++ ) {
			record = data.records[i];
			for ( j = 0; j < 2; j++ ) {
				order = ( j === 0 ) ? 'row-major' : 'column-major';
				lda = ( j === 0 ) ? record.N+2 : record.M+2;
				sa1 = ( j === 0 ) ? lda : 1;
				sa2 = ( j === 0 ) ? 1 : lda;
				A = storage( record, sa1, sa2, 0 );
				before = new Uint8Array( new Uint8Array( A.buffer, A.byteOffset, A.byteLength ) );
				for ( k = 0; k < norms.length; k++ ) {
					norm = norms[k];
					work = new Float64Array( record.M+2 );
					work[ record.M ] = 987.0;
					out = dlantr( order, norm, record.uplo, record.diag, record.M, record.N, A, lda, work );
					compare( t, out, decode( record.expected[norm] ), record.name+' '+order+' '+norm );
					t.strictEqual( work[record.M], 987.0, 'workspace guard preserved' );
				}
				t.deepEqual( new Uint8Array( A.buffer, A.byteOffset, A.byteLength ), before, 'input and matrix padding unchanged' );
			}
		}
		t.end();
	});

	tape( name+': alternative strides, offsets, and negative workspace stride', opts, function test( t ) {
		var record;
		var before;
		var norms;
		var work;
		var norm;
		var sa1;
		var sa2;
		var out;
		var oa;
		var A;
		var i;
		var j;
		var k;
		var q;

		norms = [ 'max', 'one', 'infinity', 'frobenius' ];
		for ( i = 0; i < data.records.length; i++ ) {
			record = data.records[i];
			for ( j = 0; j < 2; j++ ) {
				sa1 = 2*(record.N+2);
				sa2 = 2;
				oa = 3;
				if ( j === 1 ) {
					oa += ((record.M-1)*sa1) + ((record.N-1)*sa2);
					sa1 *= -1;
					sa2 *= -1;
				}
				A = storage( record, sa1, sa2, oa );
				before = new Uint8Array( new Uint8Array( A.buffer, A.byteOffset, A.byteLength ) );
				for ( k = 0; k < norms.length; k++ ) {
					norm = norms[k];
					work = new Float64Array( (record.M*2)+5 );
					for ( q = 0; q < work.length; q++ ) {
						work[q] = 987.0;
					}
					out = dlantr.ndarray( norm, record.uplo, record.diag, record.M, record.N, A, sa1, sa2, oa, work, -2, record.M*2 );
					compare( t, out, decode( record.expected[norm] ), record.name+' ndarray '+norm );
					t.strictEqual( work[0], 987.0, 'workspace prefix guard preserved' );
					t.strictEqual( work[1], 987.0, 'workspace gap guard preserved' );
					t.strictEqual( work[work.length-1], 987.0, 'workspace suffix guard preserved' );
				}
				t.deepEqual( new Uint8Array( A.buffer, A.byteOffset, A.byteLength ), before, 'input and matrix padding unchanged' );
			}
		}
		t.end();
	});

	tape( name+': empty matrices and unused workspace are not accessed', opts, function test( t ) {
		var norms;
		var out;
		var A;
		var i;

		norms = [ 'max', 'one', 'infinity', 'frobenius' ];
		for ( i = 0; i < norms.length; i++ ) {
			out = dlantr( 'row-major', norms[i], 'upper', 'unit', 0, 3, null, 3, null );
			t.strictEqual( 1.0/out, Infinity, 'zero rows return positive zero without storage' );
			out = dlantr.ndarray( norms[i], 'lower', 'non-unit', 3, 0, null, null, null, null, null, null, null );
			t.strictEqual( 1.0/out, Infinity, 'zero columns return positive zero without storage' );
		}
		A = new Float64Array( [ 2.0 ] );
		out = dlantr.ndarray( 'max', 'upper', 'non-unit', 1, 1, A, 1, 1, 0, null, undefined, undefined );
		t.strictEqual( out, 2.0, 'non-infinity workspace and its indexing metadata ignored' );
		out = dlantr( 101, 'max', 121, 131, 1, 1, A, 1, null );
		t.strictEqual( out, 2.0, 'standard layout, triangle and diagonal enums supported' );
		out = dlantr.ndarray( 'one', 'upper', 'non-unit', 1, 3, A, 0, 0, 0, null, 0, 0 );
		t.strictEqual( out, 2.0, 'zero input strides preserve aliasing semantics for column sums' );
		t.end();
	});

	tape( name+': invalid options and storage throw before numerical evaluation', opts, function test( t ) {
		var work = new Float64Array( 2 );
		var A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
		t.throws( function f() {
			dlantr( 'bad', 'max', 'upper', 'unit', 2, 2, A, 2, work );
		}, TypeError, 'invalid layout' );
		t.throws( function f() {
			dlantr( 'row-major', '__proto__', 'upper', 'unit', 2, 2, A, 2, work );
		}, TypeError, 'inherited norm property rejected' );
		t.throws( function f() {
			dlantr( 'row-major', 'max', 'all', 'unit', 2, 2, A, 2, work );
		}, TypeError, 'invalid triangle' );
		t.throws( function f() {
			dlantr( 'row-major', 'max', 'upper', 'bad', 2, 2, A, 2, work );
		}, TypeError, 'invalid diagonal' );
		t.throws( function f() {
			dlantr( 'row-major', 'max', 'upper', 'unit', 3, 2, A, 2, work );
		}, RangeError, 'invalid upper trapezoid' );
		t.throws( function f() {
			dlantr( 'row-major', 'max', 'lower', 'unit', 2, 3, A, 3, work );
		}, RangeError, 'invalid lower trapezoid' );
		t.throws( function f() {
			dlantr( 'row-major', 'max', 'upper', 'unit', -1, 2, A, 2, work );
		}, RangeError, 'negative dimensions' );
		t.throws( function f() {
			dlantr( 'row-major', 'max', 'upper', 'unit', 1.5, 2, A, 2, work );
		}, RangeError, 'fractional dimensions' );
		t.throws( function f() {
			dlantr( 'column-major', 'max', 'upper', 'unit', 2, 2, A, 1, work );
		}, RangeError, 'small leading dimension' );
		t.throws( function f() {
			dlantr( 'row-major', 'max', 'upper', 'unit', 2, 2, [], 2, work );
		}, TypeError, 'matrix must be typed storage' );
		t.throws( function f() {
			dlantr( 'row-major', 'infinity', 'upper', 'unit', 2, 2, A, 2, new Float64Array( 1 ) );
		}, RangeError, 'small workspace' );
		t.throws( function f() {
			dlantr.ndarray( 'infinity', 'upper', 'unit', 2, 2, A, 2, 1, 0, work, 0, 0 );
		}, RangeError, 'zero workspace stride' );
		t.throws( function f() {
			dlantr.ndarray( 'max', 'upper', 'unit', 2, 2, A, -2, -1, 0, work, 1, 0 );
		}, RangeError, 'negative indexed input position' );
		t.end();
	});
}


// EXPORTS //

module.exports = suite;
